export const title = "Will a Monitor Arm Plate Fit a Recessed VESA Mount?";
export const metaTitle = "Monitor Arm Plates and Recessed VESA Mounts";
export const metaDescription = "Check recessed VESA geometry, plate size, approved spacers, screw requirements, and connector access before buying a monitor arm.";
